47	static a2dp_sink_packet_t* sink_sbc_repackage(uint8_t* data, uint16_t length)
48	{
49	    a2dp_sink_packet_t* packet = NULL;
50	
51	    if (length < 2) {
52	        BT_LOGE("%s, invaild length: %d", __func__, length);
53	        return NULL;
54	    }
55	    if (data[1] != A2DP_SBC_SYNCWORD) {
56	        BT_LOGE("%s, sbc syncword error: %02x", __func__, data[1]);
57	        return NULL;
58	    }
59	    /* pack aac loas header */
60	    packet = malloc(sizeof(a2dp_sink_packet_t) + length + LOAS_HDRSIZE);
61	    if (packet) {
62	        packet->data[0] = (LATM_HEADER >> 8) & 0xFF;
63	        packet->data[1] = (LATM_HEADER & 0xE0) | ((length >> 8) & 0x1F);
64	        packet->data[2] = length & 0xFF;
65	        packet->length = length + LOAS_HDRSIZE;
66	        memcpy(packet->data + LOAS_HDRSIZE, data, length);
67	    }
68	
69	    return packet;
70	}
