91	static void a2dp_sink_flush_packet_queue(void)
92	{
93	    struct list_node *node, *tmp;
94	
95	    list_for_every_safe(&sink_stream.packet_queue, node, tmp)
96	    {
97	        list_delete(node);
98	        free(node);
99	    }
100	}
