102	static void a2dp_sink_audio_handle_timer(service_timer_t* timer, void* arg)
103	{
104	    a2dp_sink_stream_t* stream = &sink_stream;
105	    struct list_node* queue = &stream->packet_queue;
106	    a2dp_sink_packet_t* packet = NULL;
107	    struct list_node *node, *tmp;
108	    int ret;
109	
110	    if (stream->state != STATE_RUNNING) {
111	        return;
112	    }
113	
114	    uint64_t now_us = bt_get_os_timestamp_us();
115	#ifndef CONFIG_ARCH_SIM
116	    if (stream->last_ts && ((now_us - stream->last_ts) > 30000))
117	        BT_LOGD("===a2dp cpu busy time:%" PRIu64 ", buff_cnt:%zu===", now_us - stream->last_ts, list_length(&sink_stream.packet_queue));
118	    stream->last_ts = now_us;
119	#endif
120	
121	    uv_mutex_lock(&stream->queue_lock);
122	    if (list_is_empty(queue) == true) {
123	        if (!stream->underflow_ts)
124	            stream->underflow_ts = now_us;
125	        goto out;
126	    }
127	
128	    if (stream->underflow_ts) {
129	        uint64_t miss_tick = (now_us - stream->underflow_ts) / (uint64_t)(A2DP_SINK_MEDIA_TICK_MS * 1000);
130	        if (miss_tick > 2)
131	            BT_LOGD("%s underflow, miss ticks: %" PRIu64, __func__, miss_tick);
132	        stream->underflow_ts = 0;
133	    }
134	
135	    list_for_every_safe(queue, node, tmp)
136	    {
137	        if (stream->block_ticks == 2) {
138	            BT_LOGD("%s ipc blocking, waiting for resume", __func__);
139	        }
140	
141	        packet = (a2dp_sink_packet_t*)node;
142	        ret = audio_control_write(A2DP_SINK_PROFILE_ID, packet->data, packet->length);
143	        if (ret < 0) {
144	            stream->block_ticks++;
145	            goto out;
146	        } else if (ret < packet->length) {
147	            packet->is_partial = true;
148	            memmove(packet->data, packet->data + ret, packet->length - ret);
149	            packet->length -= ret;
150	            stream->block_ticks++;
151	            goto out;
152	        } else {
153	            if (stream->block_ticks > 0) {
154	                BT_LOGD("%s ipc blocking resume, block ticks:%" PRIu32, __func__, stream->block_ticks);
155	                stream->block_ticks = 0;
156	            }
157	        }
158	
159	        list_delete(node);
160	        if (sink_stream.stream_interface)
161	            sink_stream.stream_interface->packet_send_done(packet);
162	    }
163	out:
164	    uv_mutex_unlock(&stream->queue_lock);
165	}
