167	void a2dp_sink_packet_receive(a2dp_sink_packet_t* packet)
168	{
169	    a2dp_sink_stream_t* stream = &sink_stream;
170	    struct list_node* queue = &stream->packet_queue;
171	
172	    if (packet == NULL)
173	        return;
174	
175	    if (stream->state != STATE_RUNNING) {
176	        free(packet);
177	        return;
178	    }
179	
180	    uv_mutex_lock(&stream->queue_lock);
181	    if (list_length(queue) == A2DP_MAX_ENQUEUE_PACKET_COUNT) {
182	        a2dp_sink_packet_t* pkt = (a2dp_sink_packet_t*)list_peek_head(queue);
183	
184	        if (pkt && pkt->is_partial) {
185	            // The list head element has already been partially sent and cannot be deleted. Delete the next packet.
186	            FAR struct list_node* node = list_next(queue, &pkt->node);
187	
188	            if (node) {
189	                list_delete(node);
190	                free(node);
191	                list_add_tail(queue, &packet->node);
192	            } else {
193	                free(packet);
194	            }
195	        } else {
196	            free(list_remove_head(queue));
197	            list_add_tail(queue, &packet->node);
198	        }
199	
200	        uv_mutex_unlock(&stream->queue_lock);
201	        return;
202	    }
203	
204	    list_add_tail(queue, &packet->node);
205	
206	    if (list_length(queue) >= A2DP_MAX_DELAY_PACKET_COUNT && !stream->media_alarm) {
207	        BT_LOGD("%s start trans packet", __func__);
208	        stream->underflow_ts = 0;
209	        stream->last_ts = 0;
210	        stream->block_ticks = 0;
211	        sink_stream.media_alarm = service_loop_timer(10,
212	            A2DP_SINK_MEDIA_TICK_MS, a2dp_sink_audio_handle_timer, NULL);
213	        if (sink_stream.media_alarm == NULL)
214	            BT_LOGE("%s, media_alarm start error", __func__);
215	    }
216	
217	    uv_mutex_unlock(&stream->queue_lock);
218	}
